package com.example.agenticai.agent; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.*; @Component public class OllamaClient {private final RestClient c; private final String model; public OllamaClient(org.springframework.core.env.Environment e){c=RestClient.builder().baseUrl(e.getProperty("agent.ollama.base-url","http://localhost:11434")).build();model=e.getProperty("agent.ollama.model","qwen3:8b");} public String chat(List<Map<String,String>>m){Map<String,Object>b=Map.of("model",model,"messages",m,"stream",false);Map r=c.post().uri("/api/chat").body(b).retrieve().body(Map.class);return String.valueOf(((Map)r.get("message")).get("content"));}}
